import { useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Activity, ArrowDownToLine, ArrowUpRight, Bell, BookOpen, CalendarClock, Check, ChevronRight, CircleHelp, Clock3, Dumbbell, Flame, Gauge, Gem, History, Layers3, Pause, Play, Plus, RotateCw, Shield, ShoppingBag, Sparkles, Swords, Target, Trophy, UserRound, Volume2, VolumeX, X, Zap } from 'lucide-react';
import { loadData, saveData, upgradeData } from './db';
import { addLocalDays, awardMissionCompletion, categories, categoryIcons, checklistSatisfied, elapsedTimerMs, generateDailyQuests, localDateKey, localDayEnd, recordDailyStreak, rewardForDifficulty, templates, updateDeadlineStatuses, validateResult } from './questEngine';
import { playSystemSound, playUiClick, primeSystemAudio, soundEvents } from './sound';
import type { SoundEvent } from './sound';
import { createCustomReward, equipShopItem, purchaseShopItem, useShopItem } from './shopEngine';
import { ShopScreen } from './Shop';
import type { ActivityEntry, AppData, Mission, MissionPeriod, MissionStatus, RankId, Tab, VerificationAttempt, VerificationMethod } from './types';
